const PORT = int(process.env.PORT, 55750);
const BIND = process.env.BIND || '0.0.0.0';


// Windows ServerHost integration. The token is random and exists only for the
// lifetime of the supervised Node process; it enables loopback-only private
// lifecycle routes and distinguishes the Windows runtime from normal Node/Docker use.
const DX_WINDOWS_LAUNCHER_TOKEN = String(process.env.DX_WINDOWS_LAUNCHER_TOKEN || '').trim();
const DX_WINDOWS_SHUTDOWN_MARKER = String(process.env.DX_WINDOWS_SHUTDOWN_MARKER || '').trim();

function ensureWindowsPortableFirewallAccess() {
  if (process.platform !== 'win32' || !DX_WINDOWS_LAUNCHER_TOKEN) return;
  if (!(BIND === '0.0.0.0' || BIND === '::')) return;
  const ruleName = `Direct-Xfer-TCP-${PORT}`;

  // Do not trust a rule merely because its display name exists. A previous
  // Direct-Xfer run, a manual edit or Windows migration can leave a disabled,
  // outbound, wrong-port or overly broad rule behind. Query the structured
  // firewall objects (property names are stable across Windows UI languages)
  // and only accept the exact inbound/TCP/port/LocalSubnet contract.
  const escapedName = ruleName.replace(/'/g, "''");
  const inspectPs = [
    `$n='${escapedName}';`,
    '$ok=$false;',
    'Get-NetFirewallRule -DisplayName $n -ErrorAction SilentlyContinue | ForEach-Object {',
    " if ($_.Enabled -eq 'True' -and $_.Direction -eq 'Inbound' -and $_.Action -eq 'Allow') {",
    '  $r=$_; $p=$r | Get-NetFirewallPortFilter -ErrorAction SilentlyContinue; $a=$r | Get-NetFirewallAddressFilter -ErrorAction SilentlyContinue;',
    `  if ($p -and $p.Protocol -eq 'TCP' -and [string]$p.LocalPort -eq '${PORT}' -and $a -and @($a.RemoteAddress) -contains 'LocalSubnet') { $ok=$true }`,
    ' }',
    '};',
    "if ($ok) { Write-Output 'DX_FIREWALL_OK' }",
  ].join('');
  execFile('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', inspectPs], {
    windowsHide:true,
    timeout:15000,
    maxBuffer:256 * 1024,
  }, (inspectErr, stdout) => {
    if (!inspectErr && String(stdout || '').includes('DX_FIREWALL_OK')) {
      console.log(`  • Windows Firewall : rule ready for TCP ${PORT} (local subnet)`);
      return;
    }

    // The portable EXE normally runs unelevated. Ask Windows for elevation only
    // if the exact rule is absent/invalid. Delete stale rules with our generated
    // name before recreating one so duplicate or disabled rules cannot shadow the
    // effective policy. The final rule is port-scoped and LocalSubnet-only.
    const elevatedPs = [
      `$n='${escapedName}';`,
      'Get-NetFirewallRule -DisplayName $n -ErrorAction SilentlyContinue | Remove-NetFirewallRule -ErrorAction SilentlyContinue;',
      `New-NetFirewallRule -DisplayName $n -Direction Inbound -Action Allow -Protocol TCP -LocalPort ${PORT} -Profile Any -RemoteAddress LocalSubnet -ErrorAction Stop | Out-Null`,
    ].join('');
    const encoded = Buffer.from(elevatedPs, 'utf16le').toString('base64');
    const ps = `$p=Start-Process -FilePath 'powershell.exe' -Verb RunAs -ArgumentList @('-NoProfile','-NonInteractive','-EncodedCommand','${encoded}') -Wait -PassThru; exit $p.ExitCode`;
    execFile('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', ps], {
      windowsHide:true,
      timeout:120000,
      maxBuffer:256 * 1024,
    }, (elevErr) => {
      if (elevErr) {
        console.warn(`[windows] Firewall rule was not created (${elevErr.message}). Local access remains available; LAN access may be blocked. Allow TCP ${PORT} for Direct-Xfer from the local subnet in Windows Defender Firewall.`);
        return;
      }
      console.log(`  • Windows Firewall : TCP ${PORT} allowed from the local subnet`);
    });
  });
}

