  const goal = Math.max(0, Math.floor(Number(s.notifyDownloadThreshold) || 0));
  if (goal <= 0 || (s.downloads || 0) < goal) return;
  if (s.downloadThresholdNotifiedAt) return; // already alerted for this goal
