// A visitor submits the access-request form on a locked link. Creates
// one pending request per browser (tracked by cookie) and pings the admin. Plain
// form POST + redirect, so it works without JavaScript.
const requestAccessParser = express.urlencoded({ extended: false, limit: '8kb' });
downloadRouter.post('/s/:token/request-access', requestAccessParser, (req, res) => {
  const s = getByToken(req.params.token);
  if (!s || !isActive(s) || !s.requestAccess) return sendError(req, res, 404, 'shareGone');
  const rel = linkPrefix(s) + req.params.token;
  // Already tracked on this browser (pending/approved/denied) — don't pile up duplicates.
  if (pendingAccessRequest(req, s)) return res.redirect(302, rel);
  const name = String((req.body && req.body.name) || '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, 80);
  const email = String((req.body && req.body.email) || '').replace(/[\r\n\t ]+/g, '').trim().slice(0, 200);
  const message = String((req.body && req.body.message) || '').replace(/\r\n/g, '\n').trim().slice(0, 1000);
  if (!name) return res.status(400).type('html').send(accessRequestPage(pickLang(req), s, req.params.token, null));
  const decisionSnapshot = snapshotPublicMessageDecision(req, s.token);
  const decision = publicMessageDecision(req, s.token, name + '\n' + message, 'access-request');
  if (decision.retryAfter) {
    res.setHeader('Retry-After', String(decision.retryAfter));
    return res.status(429).type('html').send(errorPage(pickLang(req), 429, (PUB[pickLang(req)] || PUB.en).tooManyReq));
  }
  const ip = String(clientIp(req) || '').replace(/^::ffff:/i, '');
  // A client may retry after the original redirect/cookie response was lost. The
  // anti-abuse layer already recognizes that payload as a duplicate; reuse the
  // existing pending request instead of creating another durable row.
  if (decision.duplicate) {
    const prior = Array.isArray(s.accessRequests) ? s.accessRequests.find((row) => row && row.status === 'pending' &&
      String(row.ip || '') === ip && String(row.name || '') === name && String(row.email || '') === email &&
      String(row.message || '') === message && (Date.now() - (Number(row.at) || 0)) < PUBLIC_MESSAGE_DUP_MS) : null;
    if (prior && prior.id) setAccessRequestCookie(req, res, s, prior.id);
    return res.redirect(302, rel);
  }
  const geo = geoSync(ip) || {};
  const previousRequests = Array.isArray(s.accessRequests) ? JSON.parse(JSON.stringify(s.accessRequests)) : null;
  if (!Array.isArray(s.accessRequests)) s.accessRequests = [];
  const id = crypto.randomBytes(12).toString('hex');
  s.accessRequests.unshift({ id, name, email: email || null, message: message || null, at: Date.now(), ip, country: geo.country || null, flag: geo.flag || '🌐', status: 'pending', decidedAt: 0, decidedBy: null });
  if (s.accessRequests.length > ACCESS_REQUESTS_MAX) s.accessRequests.length = ACCESS_REQUESTS_MAX;
  if (!persistNow()) {
    if (previousRequests) s.accessRequests = previousRequests; else delete s.accessRequests;
    restorePublicMessageDecision(decisionSnapshot);
    return res.status(503).type('html').send(errorPage(pickLang(req), 503, 'Unable to save this request. Please retry.'));
  }
  geolocate(ip).catch(() => {});
  setAccessRequestCookie(req, res, s, id);
  emitLiveActivity('visitor', { shareId:s.id, name:s.name, status:'access-request', detail:'access request submitted', ip:pubIp(ip) });
  if (decision.notify) notify('message', { name: s.name, shareId: s.id, ip, country: geo.country, text: `Access request — ${name}${email ? ` <${email}>` : ''}${message ? `: ${message}` : ''}`, file: null });
  res.redirect(302, rel);
});

// A visitor leaves moderated feedback on a shared file. Private to the
// admin (never shown to other visitors). Plain form POST + redirect (no JS needed).
const feedbackParser = express.urlencoded({ extended: false, limit: '8kb' });
downloadRouter.post('/s/:token/feedback', feedbackParser, (req, res) => {
  const s = getByToken(req.params.token);
  if (!s || !isActive(s) || !s.allowFeedback) return sendError(req, res, 404, 'shareGone');
  if (s.pwHash && !isUnlocked(req, s)) return res.status(401).type('html').send(passwordPage(pickLang(req), s, false, req.params.token));
  if (s.requestAccess && !isAccessApproved(req, s)) return res.status(401).type('html').send(accessRequestPage(pickLang(req), s, req.params.token, pendingAccessRequest(req, s)));
  const rel = linkPrefix(s) + req.params.token;
  // Return the visitor to the page they were on (same share only, to avoid an open
  // redirect), with a flag the page uses to show a thank-you note.
  let back = rel;
  try { const u = new URL(String(req.get('referer') || ''), primaryBase(req)); if (u.pathname.startsWith(linkPrefix(s) + req.params.token)) back = u.pathname; } catch (_) {}
  const name = String((req.body && req.body.name) || '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, 80);
  const body = String((req.body && req.body.body) || '').replace(/\r\n/g, '\n').trim().slice(0, 2000);
  if (!body) return res.redirect(302, back);
  const decisionSnapshot = snapshotPublicMessageDecision(req, s.token);
  const decision = publicMessageDecision(req, s.token, body, 'feedback');
  if (decision.retryAfter) {
    res.setHeader('Retry-After', String(decision.retryAfter));
    return res.status(429).type('html').send(errorPage(pickLang(req), 429, (PUB[pickLang(req)] || PUB.en).fbError || 'Please wait a moment and retry.'));
  }
  if (!decision.duplicate) {
    const ip = String(clientIp(req) || '').replace(/^::ffff:/i, '');
    const geo = geoSync(ip) || {};
    const previousFeedback = Array.isArray(s.visitorFeedback) ? JSON.parse(JSON.stringify(s.visitorFeedback)) : null;
    if (!Array.isArray(s.visitorFeedback)) s.visitorFeedback = [];
    s.visitorFeedback.unshift({ id: crypto.randomBytes(8).toString('hex'), at: Date.now(), ip, country: geo.country || null, flag: geo.flag || '🌐', name: name || null, body, read: false });
    if (s.visitorFeedback.length > VISITOR_FEEDBACK_MAX) s.visitorFeedback.length = VISITOR_FEEDBACK_MAX;
    if (!persistNow()) {
      if (previousFeedback) s.visitorFeedback = previousFeedback; else delete s.visitorFeedback;
      restorePublicMessageDecision(decisionSnapshot);
      return res.status(503).type('html').send(errorPage(pickLang(req), 503, 'Unable to save this feedback. Please retry.'));
    }
    geolocate(ip).catch(() => {});
    emitLiveActivity('visitor', { shareId:s.id, name:s.name, status:'feedback', detail:name ? 'feedback submitted · ' + name : 'feedback submitted', ip:pubIp(ip) });
    if (decision.notify) notify('message', { name: s.name, shareId: s.id, ip, country: geo.country, text: `Feedback${name ? ` — ${name}` : ''}: ${body}`, file: null });
  }
  res.redirect(302, back + (back.includes('?') ? '&' : '?') + 'feedback=sent');
});

// ===================================================================
//  ADMIN ROUTES: protected API
// ===================================================================

const adminRouter = express.Router();
adminRouter.use(requireAuth);
// Authenticated API responses can contain paths, identities and configuration.
// Do not leave those responses in browser or intermediary caches.
adminRouter.use((req, res, next) => {
  res.setHeader('Cache-Control', 'no-store');
  next();
});
// Enforce the mandatory first-login/reset password change on the server. The UI
// prompt alone is not an authorization boundary and can be bypassed with direct
// API calls.
adminRouter.use((req, res, next) => {
  const acc = req.session && req.session.accountId ? getAccountById(req.session.accountId) : null;
  if (!accountNeedsPwChange(acc)) return next();
  if (req.path === '/session' || req.path === '/password' || req.path === '/logout') return next();
  return res.status(403).json({ error: 'password-change-required' });
});

// --- Granular roles (feature) -----------------------------------------------
// owner/admin: full access. operator: create links + manage ONLY their own,
// no global settings/accounts. auditor: read-only everywhere.
function ownsShare(req, s) {
  const role = req.session && req.session.role;
  // Auditors are globally read-only, but may inspect every link.
  if (role === 'owner' || role === 'admin' || role === 'auditor') return true;
  return !!(s && s.ownerId && s.ownerId === req.session.accountId);
}
function stampOwner(share, req) {
  share.ownerId = req.session.accountId || null;
  share.ownerName = req.session.username || null;
  return share;
}
function requireFullAdmin(req, res, next) {
  const role = req.session && req.session.role;
  if (role === 'owner' || role === 'admin') return next();
  return res.status(403).json({ error: 'forbidden' });
}
function requireAuditAccess(req, res, next) {
  const role = req.session && req.session.role;
  if (role === 'owner' || role === 'admin' || role === 'auditor') return next();
  return res.status(403).json({ error: 'forbidden' });
}
// Authorization gate applied to every /api admin route (after requireAuth).
adminRouter.use((req, res, next) => {
  const role = req.session.role;
  if (role === 'owner' || role === 'admin') return next();
  const isRead = ['GET', 'HEAD', 'OPTIONS'].includes(req.method);
  if (role === 'auditor') {
    // Notification-center mutations below only change this account's personal inbox
    // state. Keep the exception explicit so a future /notifications/* admin action
    // does not accidentally become writable by the read-only auditor role.
    const ownNotificationMutation =
      (req.method === 'POST' && (req.path === '/notifications/read' || req.path === '/notifications/prefs' || req.path === '/notification-rules')) ||
      (req.method === 'DELETE' && (req.path === '/notifications' || /^\/notifications\/[^/]+$/.test(req.path) || /^\/notification-rules\/[^/]+$/.test(req.path)));
    return (isRead || ownNotificationMutation) ? next() : res.status(403).json({ error: 'read-only' });
  }
  if (role === 'operator') {
    if (isRead) return next();
    const p = req.path;
    // Global admin surfaces an operator can't change.
    if (/^\/(settings|accounts|ip-names|backup-now|backup-test|shutdown|history|network\/port-check)\b/.test(p)) return res.status(403).json({ error: 'forbidden' });
    if (/^\/(webhook-test|email-test|digest-test)\b/.test(p)) return res.status(403).json({ error: 'forbidden' });
    if (/^\/shares\/(export|import)\b/.test(p)) return res.status(403).json({ error: 'forbidden' });
    // Per-share ownership for /shares/:id/... (create routes are handled inline).
    const m = /^\/shares\/([^/]+)/.exec(p);
    if (m && !['bulk', 'export', 'import'].includes(m[1])) {
      const s = getById(m[1]);
      if (s && !ownsShare(req, s)) return res.status(403).json({ error: 'forbidden' });
    }
    return next();
  }
  // Unknown or corrupted roles never inherit administrative privileges.
  return res.status(403).json({ error: 'forbidden' });
});

function externalProto(req) {
  // req.protocol already honors X-Forwarded-Proto only when the peer is a
  // configured trusted proxy. Never accept that header independently.
  return req && req.protocol === 'https' ? 'https' : 'http';
}

// True when a Host header value (optionally with a port) is a bare IP literal
// rather than a domain name. Behind a reverse proxy the forwarded Host is often
// the container's LAN IP (e.g. "192.168.50.11:55750"); such a value must NOT be
// used as the default link base — only a real domain name may override the
// public IP.
function hostIsIpLiteral(host) {
  let h = String(host || '').trim();
  if (!h) return false;
  if (h[0] === '[') return true; // "[::1]:443" — bracketed IPv6 literal
  const c = h.indexOf(':');
  if (c !== -1 && c === h.lastIndexOf(':')) h = h.slice(0, c); // strip :port (IPv4/hostname)
  return /^\d{1,3}(\.\d{1,3}){3}$/.test(h); // IPv4 literal
}

// Normalizes an admin-entered domain/URL to an origin. '' if empty, null if invalid.
function normalizeLinkBase(raw) {
  let s = String(raw == null ? '' : raw).trim();
  if (!s) return '';
  s = s.replace(/\/+$/, '');
  if (!/^https?:\/\//i.test(s)) {
    s = (/:\d+$/.test(s) ? 'http://' : 'https://') + s;
  }
  try {
    const u = new URL(s);
    if (!u.hostname) return null;
    return `${u.protocol}//${u.host}`;
  } catch (_) {
    return null;
  }
}

// Link URL base: configured domain > PUBLIC_URL > reverse-proxy domain > PUBLIC_HOST > public IP > local IP.
// The reverse-proxy Host is honored ONLY when it is a real domain name; a bare
// IP (typically the container's LAN IP) is skipped so the default remains the
// public IP — a shareable link outside the local network.
function primaryBase(req) {
  const configured = getSettings().linkBase;
  if (configured) return configured;
  if (PUBLIC_URL) return PUBLIC_URL;
  // Behind a reverse proxy, the request host can be the real external domain —
  // but only if it actually is a domain. If the proxy forwards a bare IP as
  // Host, ignore it and fall through to the public IP below.
  if (TRUST_PROXY) {
    const host = String(req.get('host') || '').trim();
    // A request Host is untrusted input. Restrict it to a plain hostname/IP and
    // optional port before embedding it into links shown to the administrator.
    let validHost = false;
    if (/^[A-Za-z0-9.:[\]-]+$/.test(host)) {
      try { validHost = !!new URL(`http://${host}`).hostname; } catch (_) {}
    }
    if (validHost && !hostIsIpLiteral(host)) return `${externalProto(req)}://${host}`;
  }
  if (PUBLIC_HOST) return `http://${PUBLIC_HOST}:${PORT}`;
  // Default: public IP, for a link shareable outside the local network.
  const ip = getPublicIPCached();
  if (ip) return `http://${ip}:${PORT}`;
  const locals = getLocalIPv4s();
  if (locals.length) return `http://${locals[0].address}:${PORT}`;
  return '';
}

function decorateShare(s, req) {
  const active = isActive(s);
  const items = shareItems(s);
  const rel = linkPrefix(s) + s.token;
  const base = primaryBase(req);
  return {
    id: s.id,
    token: s.token,
    type: s.type,
    name: s.name,
    hostPath: s.hostPath,
    relDir: s.relDir,
    size: s.size,
    createdAt: s.createdAt,
    startsAt: s.startsAt || null,
    expiresAt: s.expiresAt,
    effectiveExpiresAt: shareEffectiveExpiry(s),
    maxDownloads: s.maxDownloads,
    downloadsUsed: s.downloads || 0, // raw quota counter; dashboard stats may have a reset baseline
    downloads: Math.max(0, (s.downloads || 0) - shareStatsBaseline(s).downloads),
    maxVisitors: parseMaxVisitors(s.maxVisitors), // 0 = unlimited
    notifyDownloadThreshold: s.notifyDownloadThreshold || 0, // download-goal alert (0 = off)
    downloadThresholdReached: !!s.downloadThresholdNotifiedAt,
    uniqueVisitorsUsed: Array.isArray(s.visitors) ? s.visitors.length : 0,
    uniqueVisitors: Math.max(0, (Array.isArray(s.visitors) ? s.visitors.length : 0) - shareStatsBaseline(s).visitors),
    views: Math.max(0, (s.views || 0) - shareStatsBaseline(s).views), // resettable dashboard counter
    pinned: !!s.pinned,
    archived: !!s.archived,
    logicalBytes: shareLogicalBytes(s),
    logicalBytesReady: !shareNeedsLogicalBytesScan(s) || !!shareLogicalBytesCache.get(s.id),
    itemCount: shareLogicalFileCount(s),
    lastActivityAt: shareActivityAt(s),
    lastUseAt: shareLastUseAt(s),
    lastDownload: s.lastDownload ? { ...s.lastDownload, ip: pubIp(s.lastDownload.ip) } : null,
    lastUpload: s.lastUpload ? { ...s.lastUpload, ip: pubIp(s.lastUpload.ip) } : null,
    expirySetAt: s.expirySetAt || s.createdAt || null,
    inactiveExpiresAt: shareInactiveDeadline(s),
    firstUsedAt: s.firstUsedAt || null,
    firstUseExpiresAt: shareFirstUseDeadline(s),
    firstUseExpirySeconds: Math.max(0, Number(s.firstUseExpirySeconds) || 0),
    inactiveExpirySeconds: Math.max(0, Number(s.inactiveExpirySeconds) || 0),
    expiryReminderHours: s.expiryReminderHours == null ? null : Number(s.expiryReminderHours),
    color: s.color || '',
    descriptionMd: s.descriptionMd || '',
    commentCount: Array.isArray(s.adminComments) ? s.adminComments.length : 0,
    lastComment: Array.isArray(s.adminComments) && s.adminComments.length ? s.adminComments[0] : null,
    // Access-request gate + pending count. feedback counts.
    requestAccess: !!s.requestAccess,
    accessPending: Array.isArray(s.accessRequests) ? s.accessRequests.filter((r) => r && r.status === 'pending').length : 0,
    accessRequestsCount: Array.isArray(s.accessRequests) ? s.accessRequests.length : 0,
    allowFeedback: !!s.allowFeedback,
    feedbackCount: Array.isArray(s.visitorFeedback) ? s.visitorFeedback.length : 0,
    feedbackUnread: Array.isArray(s.visitorFeedback) ? s.visitorFeedback.filter((f) => f && !f.read).length : 0,
    statsResetAt: s.statsBaseline && s.statsBaseline.at || null,
    changeCount: Array.isArray(s.changeHistory) ? s.changeHistory.length : 0,
    dlp: s.dlp ? { ...s.dlp } : null,
    favorite: s.type === 'photo' ? !!s.favorite : false,
    // Images page — direct image links (full-size + thumbnail), no relay page.
    // They can use their own optional domain (imageBase), else the main link base.
    photo: s.type === 'photo' ? (() => {
      const ib = getSettings().imageBase || base;
      const ps = photoStatsOf(s);
      const rev = photoCacheRevision(s);
      const qv = '?v=' + encodeURIComponent(rev);
      return {
        ext: photoExt(s),
        imgUrl: (ib ? ib + '/i/' + s.token + '.' + photoExt(s) : ('/i/' + s.token + '.' + photoExt(s))) + qv,
        thumbUrl: (ib ? ib + '/i/' + s.token + '/thumb' : ('/i/' + s.token + '/thumb')) + qv,
        microUrl: (ib ? ib + '/i/' + s.token + '/micro' : ('/i/' + s.token + '/micro')) + qv,
        hasThumb: !!s.thumb,
        hasMicro: !!s.micro,
        fullViews: ps.full.v || 0,
        fullVisitors: Array.isArray(ps.full.u) ? ps.full.u.length : 0,
        thumbViews: ps.thumb.v || 0,
        thumbVisitors: Array.isArray(ps.thumb.u) ? ps.thumb.u.length : 0,
        microViews: ps.micro.v || 0,
        microVisitors: Array.isArray(ps.micro.u) ? ps.micro.u.length : 0,
        w: s.w || null,
        h: s.h || null,
        uploadDeviceName: photoUploadDeviceName(s),
        metadataRemoved: !!s.metadataRemoved,
        cacheRevision: photoCacheRevision(s),
        versionCount: Array.isArray(s.versions) ? s.versions.length : 0,
        editHistoryCount: Array.isArray(s.editHistory) ? s.editHistory.length : 0,
      };
    })() : null,
    // Shareable image gallery: a public /g/<token> page over member images.
    album: s.type === 'album' ? (() => {
      const ib = getSettings().imageBase || base;
      return {
        count: Array.isArray(s.members) ? s.members.length : 0,
        members: Array.isArray(s.members) ? s.members.slice(0, 500) : [],
        url: ib ? ib + '/g/' + s.token : ('/g/' + s.token),
      };
    })() : null,
    items: items ? items.map((it) => ({ name: it.name, size: it.size, type: it.type })) : null,
    collection: !!s.collection, // true = a genuine multi-file bundle (keep listing its files even at 1)
    adminNote: s.adminNote || null, // private admin comment (never sent to visitors)
    disabled: !!s.disabled, // manually paused (reversible) — active is false while paused
    revoked: !!s.revoked, // retained revoked/burned record; can be safely reactivated while backing data exists

    active,
    scheduled: isScheduled(s),
    hasPassword: !!s.pwHash,
    pwHint: s.pwHash ? (s.pwHint || '') : '', // only meaningful with a password
    maxDownloadsPerIp: Math.max(0, Number(s.maxDownloadsPerIp) || 0), // 0 = unlimited
    emoji: s.emoji || '', // link marker
    maxBytesServed: Math.max(0, Number(s.maxBytesServed) || 0), // 0 = unlimited
    bytesServed: Math.max(0, Number(s.bytesServed) || 0), // running total
    encrypted: !!s.encrypted, // end-to-end encrypted (server holds only ciphertext)
    encMode: s.encrypted ? (s.encMode || 'key') : null,
    allowZip: s.allowZip !== false, // false = "download all as .zip" disabled
    noPreview: !!s.noPreview, // true = in-browser preview disabled
    burnAfterDownload: !!s.burnAfterDownload, // one-time link (revokes after 1st complete DL)
    burnedAt: s.burnedAt || null, // when a one-time link actually burned
    tags: Array.isArray(s.tags) ? s.tags : [], // admin labels for grouping/filtering
    // Geo/IP access rules.
    geoMode: s.geoMode || null,
    geoCountries: Array.isArray(s.geoCountries) ? s.geoCountries : [],
    ipMode: s.ipMode || null,
    ipList: Array.isArray(s.ipList) ? s.ipList : [],
    ownerId: s.ownerId || null, // account that created the link (role scoping)
    ownerName: s.ownerName || null,
    note: s.note || '', // optional admin message shown to the visitor
    rateKBps: s.rateBps > 0 ? Math.round(s.rateBps / 1024) : 0, // 0 = unlimited
    path: rel,
    url: base ? base + rel : null,
    // Reception-link quotas / filters (undefined on non-inbox shares).
    inbox: s.type === 'inbox' ? {
      maxFiles: s.maxFiles || 0,
      maxFileBytes: s.maxFileBytes || 0,
      maxTotalBytes: s.maxTotalBytes || 0,
      bytesReceived: s.bytesReceived || 0,
      allowExt: Array.isArray(s.allowExt) ? s.allowExt : [],
      blockExt: Array.isArray(s.blockExt) ? s.blockExt : [],
      note: s.note || '',
      messages: Array.isArray(s.messages) ? s.messages : [],
      groupBySender: !!s.groupBySender,
      tagBySender: !!s.tagBySender,
      rejectDuplicates: !!s.rejectDuplicates,
      requireSenderName: !!s.requireSenderName,
      blockExecutables: !!s.blockExecutables,
      maxFilesPerSender: s.maxFilesPerSender || 0,
      maxBytesPerSender: s.maxBytesPerSender || 0,
      maxFilesPerUpload: s.maxFilesPerUpload || 0,
      moderated: !!s.moderated,
      encrypted: !!s.encrypted,
      encMode: s.encrypted ? (s.encMode || 'key') : null,
      // Live name of the mobile companion device that created this reception link
      // (null when created from the browser admin). Reflects in-app renames.
      deviceName: shareCreatorDeviceName(s),
    } : undefined,
    // Collaboration-link settings (undefined on other share types).
    collab: s.type === 'collab' ? {
      relDir: s.relDir,
      allowDelete: !!s.allowDelete,
      allowZip: s.allowZip !== false,
      maxFileBytes: s.maxFileBytes || 0,
      maxTotalBytes: s.maxTotalBytes || 0,
      maxFiles: s.maxFiles || 0,
      maxFilesPerUpload: s.maxFilesPerUpload || 0,
      bytesReceived: s.bytesReceived || 0,
      allowExt: Array.isArray(s.allowExt) ? s.allowExt : [],
      blockExt: Array.isArray(s.blockExt) ? s.blockExt : [],
      note: s.note || '',
      blockExecutables: !!s.blockExecutables,
      groupBySender: !!s.groupBySender,
      tagBySender: !!s.tagBySender,
      rejectDuplicates: !!s.rejectDuplicates,
      requireSenderName: !!s.requireSenderName,
      maxFilesPerSender: s.maxFilesPerSender || 0,
      maxBytesPerSender: s.maxBytesPerSender || 0,
      moderated: !!s.moderated,
    } : undefined,
    // Files awaiting moderation for this link (id, name, size, ip, at).
    pending: (Array.isArray(state.meta && state.meta.pending) ? state.meta.pending : [])
      .filter((p) => p.shareId === s.id)
      .map((p) => ({ id: p.id, name: p.name, size: p.size, ip: p.ip, at: p.at })),
    recipients: Array.isArray(s.recipients) ? s.recipients.map((r) => ({
      token: r.token,
      name: r.name,
      createdAt: r.createdAt || null,
      path: '/s/' + r.token,
      url: base ? base + '/s/' + r.token : null,
      downloads: (r.stats && r.stats.completed) || 0,
      stats: r.stats || null,
      // Per-recipient overrides — null = inherit the share's.
      expiresAt: r.expiresAt || null,
      maxDownloads: r.maxDownloads || null,
      // Read-receipt fields.
      viewed: !!r.viewedAt,
      viewedAt: r.viewedAt || null,
      lastViewAt: r.lastViewAt || null,
      lastViewIp: r.lastViewIp ? pubIp(r.lastViewIp) : null,
      lastViewCountry: r.lastViewCountry || null,
      lastDownloadAt: (r.stats && r.stats.lastAt) || null,
    })) : [],
    // Per-link aggregate stats (see state.stats).
    stats: displayStatsForShare(s),
  };
}

function externalTarget(req, baseOverride) {
  const proxyHost = TRUST_PROXY ? req.get('host') : '';
  const override = normalizeLinkBase(baseOverride || '') || '';
  const explicit =
    override ||
    getSettings().linkBase ||
    PUBLIC_URL ||
    (proxyHost && !hostIsIpLiteral(proxyHost) ? `${externalProto(req)}://${proxyHost}` : '');
  if (explicit) {
    try {
      const u = new URL(explicit.includes('://') ? explicit : `http://${explicit}`);
      const port = u.port ? parseInt(u.port, 10) : u.protocol === 'https:' ? 443 : 80;
      return { host: u.hostname, port, label: `${u.protocol}//${u.host}` };
    } catch (_) {}
  }
  return null;
}

// Current account for this request (guaranteed present: getSession validated it).
function currentAccount(req) { return getAccountById(req.session.accountId); }

