    scanDirUsage(PHOTO_VERSIONS_DIR), scanDirUsage(ADAPTIVE_IMAGES_DIR), scanDirUsage(ENC_DIR), scanDirUsage(SECRETS_DIR), scanDirUsage(QUARANTINE_DIR),
