  const allShares = visibleShares || listShares();
  const soonMs = 7 * DAY_MS;
  const expiringSoon = allShares
    .filter((s) => s.expiresAt && s.expiresAt > now && s.expiresAt - now <= soonMs && isActive(s))
    .sort((a, b) => a.expiresAt - b.expiresAt)
