  const names = [
    'x-forwarded-for', 'x-forwarded-proto', 'x-forwarded-host', 'x-forwarded-port',
    'x-real-ip', 'forwarded', 'via', 'x-forwarded-server', 'cf-connecting-ip',
    'cf-ray', 'x-forwarded-ssl', 'x-scheme',
  ];
