// Windows portable launcher: return the auto-generated owner password exactly
// once, only to the authenticated launcher over loopback. This restores the
// first-run desktop prompt without exposing the password through a browser URL.
app.post('/__dx_launcher/initial-admin-password', (req, res, next) => {
  if (!DX_WINDOWS_LAUNCHER_TOKEN) return next();
  if (!windowsLauncherTokenMatches(req)) return res.status(404).end();
  if (adminPwFromEnv || !ADMIN_PASSWORD_FRESH || !ADMIN_PASSWORD_PLAINTEXT_ONCE) {
    res.setHeader('Cache-Control', 'no-store');
    return res.status(204).end();
  }
  const owner = ownerAccount();
  if (!owner) return res.status(503).json({ error:'owner-unavailable' });
  const password = ADMIN_PASSWORD_PLAINTEXT_ONCE;
  const username = owner.username || ADMIN_USERNAME;
  // Serialize the response before consuming the one-time plaintext capability.
  // The stored account remains a salted scrypt hash; no plaintext is persisted.
  res.setHeader('Cache-Control', 'no-store');
  res.json({ ok:true, fresh:true, username, password });
  ADMIN_PASSWORD_FRESH = false;
  ADMIN_PASSWORD_PLAINTEXT_ONCE = null;
});

app.post('/__dx_launcher/reset-admin-password-ticket', (req, res, next) => {
  if (!DX_WINDOWS_LAUNCHER_TOKEN) return next();
  if (!windowsLauncherTokenMatches(req)) return res.status(404).end();
  const owner = ownerAccount();
  if (!owner) return res.status(503).json({ error:'owner-unavailable' });
  if (adminPwFromEnv) return res.status(409).json({ error:'env-managed' });
  // Keep at most one live recovery capability. A new tray request invalidates any
  // older browser tab so forgotten reset pages cannot remain useful indefinitely.
  windowsLauncherResetTickets.clear();
  const ticket = crypto.randomBytes(32).toString('base64url');
  windowsLauncherResetTickets.set(ticket, { expiresAt:Date.now() + 2 * 60 * 1000 });
  res.setHeader('Cache-Control', 'no-store');
  return res.json({ ok:true, ticket, expiresIn:120 });
});

app.get('/__dx_launcher/reset-admin-password', (req, res, next) => {
  if (!DX_WINDOWS_LAUNCHER_TOKEN) return next();
  if (!windowsLauncherLoopback(req)) return res.status(404).end();
  const lang = ['fr','en','es'].includes(String(req.query.lang || '')) ? String(req.query.lang) : 'en';
  const ticket = String(req.query.ticket || '');
  const rec = windowsLauncherResetTicket(ticket);
  if (!rec) return windowsLauncherSendResetPage(res, { lang, ticket:'', message:windowsLauncherResetStrings(lang).expired, showForm:false }, 410);
  if (adminPwFromEnv) return windowsLauncherSendResetPage(res, { lang, ticket:'', message:windowsLauncherResetStrings(lang).env, showForm:false }, 409);
  return windowsLauncherSendResetPage(res, { lang, ticket, showForm:true });
});

app.post('/__dx_launcher/reset-admin-password', windowsLauncherResetFormParser, (req, res, next) => {
  if (!DX_WINDOWS_LAUNCHER_TOKEN) return next();
  if (!windowsLauncherLoopback(req)) return res.status(404).end();
  const lang = ['fr','en','es'].includes(String(req.body && req.body.lang || '')) ? String(req.body.lang) : 'en';
  const tx = windowsLauncherResetStrings(lang);
  const ticket = String(req.body && req.body.ticket || '');
  const rec = windowsLauncherResetTicket(ticket);
  if (!rec) return windowsLauncherSendResetPage(res, { lang, ticket:'', message:tx.expired, showForm:false }, 410);
  if (adminPwFromEnv) return windowsLauncherSendResetPage(res, { lang, ticket:'', message:tx.env, showForm:false }, 409);
  const password = String(req.body && req.body.password || '');
  const confirm = String(req.body && req.body.confirm || '');
  if (password.length < 8 || password.length > 512) return windowsLauncherSendResetPage(res, { lang, ticket, message:tx.short, showForm:true }, 400);
  if (password !== confirm) return windowsLauncherSendResetPage(res, { lang, ticket, message:tx.mismatch, showForm:true }, 400);
  const owner = ownerAccount();
  if (!owner) return windowsLauncherSendResetPage(res, { lang, ticket, message:tx.failed, showForm:false }, 503);
  const previousAh = owner.ah, previousPwChanged = owner.pwChanged;
  owner.ah = hashPassword(password);
  owner.pwChanged = true;
  if (!persistNow()) {
    owner.ah = previousAh;
    owner.pwChanged = previousPwChanged;
    return windowsLauncherSendResetPage(res, { lang, ticket, message:tx.failed, showForm:true }, 503);
  }
  windowsLauncherResetTickets.delete(ticket);
  ADMIN_PASSWORD_FRESH = false;
  ADMIN_PASSWORD_PLAINTEXT_ONCE = null;
  clearSessionsOfAccount(owner.id);
  logAudit('password-reset', { account:owner, ip:'127.0.0.1', detail:'windows-launcher-local', suppressSecurityAlert:false });
  return windowsLauncherSendResetPage(res, { lang, ticket:'', message:tx.success, success:true, showForm:false });
});

// Windows ServerHost: process-specific loopback readiness probe. This prevents
// the desktop components from mistaking another service (or an older Direct-Xfer
// process that won a port race) for the supervised Node process.
app.get('/__dx_launcher/ready', (req, res, next) => {
  if (!DX_WINDOWS_LAUNCHER_TOKEN) return next();
  if (!windowsLauncherTokenMatches(req)) return res.status(404).end();
  res.setHeader('Cache-Control', 'no-store');
  return res.json({ ok:true, app:APP_NAME, version:APP_VERSION, pid:process.pid });
});

// Windows ServerHost: private loopback graceful-shutdown endpoint. Without the
// per-process token the route behaves as if it does not exist.
app.post('/__dx_launcher/shutdown', (req, res, next) => {
  if (!DX_WINDOWS_LAUNCHER_TOKEN) return next();
  if (!windowsLauncherTokenMatches(req)) return res.status(404).end();
  res.setHeader('Cache-Control', 'no-store');
  res.status(202).json({ ok:true });
  setTimeout(() => shutdown('windows-server-host'), 150);
});

