    type,
    hostPath: first.hostPath,
    name: first.name || first.hostPath || 'share',
    size: type === 'file' ? first.size : null,
    expiresAt: parseNewShareExpiry(body.expiresInSeconds),
    maxDownloads: parseMaxDownloads(body.maxDownloads),
